arguments.new_str:
using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9: ZipArchiveEntry now respects the UTF-8 flag and encodes names as UTF-8.
        // Legacy Java consumer expects Shift-JIS, so specify the encoding explicitly
        // to avoid setting the UTF-8 flag in the entry header.
        var shiftJis = CodePagesEncodingProvider.Instance.GetEncoding(932)
            ?? Encoding.UTF8;
        using var stream = new FileStream("data.zip", FileMode.Create);
        using var archive = new ZipArchive(stream, ZipArchiveMode.Create, leaveOpen: false, entryNameEncoding: shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

